                                                    ("IMPACT ON THE ENVIRONMENT WITHOUT PROJECT EXECUTION","impact_environment_without_project_execution", '[{"key": "1", "value": "NO SIGNIFICANT ENVIRONMENTAL IMPACT (For more information, see Table 1A of Chapter 5 in NFN-0001)"},{"key": "2", "value":"NO SIGNIFICANT ENVIRONMENTAL IMPACT. NEED FOR CORRECTIVE ACTIONS, CLEANING OR OPERATION ADEQUACY (For more information, see Table 1A of Chapter 5 in NFN-0001)"},{"key": "3","value":"WITH REVERSIBLE SIGNIFICANT ENVIRONMENTAL IMPACT ON THE OCCURRENCES IMMEDIATIONS(For more information, see Table 1A of Chapter 5 in NFN-0001)"},{"key": "4", "value":"WITH REVERSIBLE SIGNIFICANT ENVIRONMENTAL IMPACT BEYOND THE IMMEDIATIONS OF THE OCCURRENCE (For more information, see Table 1A of Chapter 5 in NFN-0001)"},{"key": "5", "value":"WITH SIGNIFICANT REVERSIBLE OR IRREVERSIBLE ENVIRONMENTAL IMPACT BEYOND THE IMMEDIATIONS OF THE OCCURRENCE. AREA PROTECTED BY LAW AFFECTED. SUSPENSION OF ENVIRONMENTAL LICENSE (For more information, see Table 1A of Chapter 5 in NFN-0001)"},{"key":"6","value":"WITH SIGNIFICANT IRREVERSIBLE ENVIRONMENTAL IMPACT BEYOND THE IMMEDIATIONS OF THE OCCURRENCE, WITH REGIONAL OR GREATER REACH(For more information, see Table 1A of Chapter 5 in NFN-0001"}]'),
                                                    ("IMPACT ON THE VALE'S REPUTATION WITHOUT PROJECT EXECUTION","impact_vale_reputation_without_execution", '[{"key": "1", "value": "No Repercussions"},{"key": "2", "value":"INTERNAL REPERCUSSION LIMITED TO THE ORGANIZATION, WITHOUT INVOLVING SOCIAL MEDIA/NETWORKS AND GOVERNMENT AUTHORITIES, INVESTORS, CUSTOMERS, SOCIAL GROUPS AND UNIONS"},{"key": "3", "value":"REGIONAL REPERCUSSION, WITH LOW  INVOLVEMENT OF SOCIAL  MEDIA/NETWORKS AND GOVERNMENTAL AUTHORITIES, INVESTORS, CLIENTS, SOCIAL GROUPS AND UNIONS"},{"key": "4", "value":"NATIONAL REPERCUSSION, WITH THE INVOLVEMENT OF SOCIAL  MEDIA/NETWORKS AND GOVERNMENTAL AUTHORITIES, INVESTORS, CLIENTS, SOCIAL GROUPS AND UNIONS"},{"key": "5", "value":"NATIONAL AND / OR INTERNATIONAL REPERCUSSION WITH INVOLVEMENT OF THE MEDIA / SOCIAL NETWORKS AND GOVERNMENTAL AUTHORITIES, INVESTORS, CLIENTS, SOCIAL GROUPS AND UNIONS WITH SIGNIFICANT EXPOSURE. MANIFESTATIONS OF MASS LOCATED."},{"key": "6", "value":"National and/or international repercussion with intense media/social media involvement and government authorities, investors, clients, social groups and trade unions with significant long-term exposure. Impact on stock price and credit rating. Condemnation of NGOs. Greater difficulty in negotiating new licenses. Localized mass manifestations."},{"key": "7", "value":"NATIONAL AND / OR INTERNATIONAL REPERCUSSION WITH INTENSE INVOLVEMENT OF SOCIAL MEDIA / NETWORKS AND GOVERNMENTAL AUTHORITIES, INVESTORS, CUSTOMERS, SOCIAL GROUPS AND UNIONS, OCCASIONING HIGH IMPACT / COMOCATION. MAY ACHIEVE STRATEGIC OBJECTIVES AND THE MISSION OF THE COMPANY. IMPACT ON SHARE PRICES AND CREDIT EVALUATION. CONDEMNATION OF NGOS. REVOCATION OF OPERATING LICENSES AND GREATER DIFFICULTY FOR TRADING NEW LICENSES. MASS MANIFESTATIONS IN MULTIPLE LOCATIONS."}]'),
                                                    ("IMPACT ON GHG EMISSIONS (Greenhouse Gases) WITH PROJECT EXECUTION","impact_on_ghg_emmisions", '[{"key": "1", "value": "INCREASES EMISSION"},{"key": "2", "value":"DOES NOT IMPACT"},{"key": "3", "value":"REDUCES EMISSION"}]'),
                                                    ("RESIDUAL BUSINESS RISK WITHOUT PROJECT EXECUTION","residual_business_risk_without_execution", '[{"key": "1", "value": "NO RISK"},{"key": "2", "value":"Low residual risk"},{"key": "3","value": "Moderate residual risk"},{"key": "4", "value":"High residual risk"},{"key":"5","value":"Very high residual risk"}]'),
                                                    ("DO YOU HAVE AUTHORIZATION FOR EXECUTION / OPERATION APPROVED AND VALID BY THE ENVIRONMENTAL AGENCY  OR DOES NOT REQUIRE ENVIRONMENTAL LICENSE?","authorization_for_execution", '[{"key": "1", "value": "PROJECT WAS NOT BY THE ENVIRONMENT AREA"},{"key": "2", "value":"PROJECT HAS ENVIRONMENTAL ASSESSMENT BY THE ENVIRONMENT AREA, REQUIRES LICENSING, BUT THE ENVIRONMENTAL STUDY WAS NOT STARTED OR WAS NOT REQUESTED FOR ENVIRONMENTAL AREA"},{"key": "3", "value":"PROJECT HAS ENVIRONMENTAL ASSESSMENT BY THE ENVIRONMENT AREA, REQUIRES LICENSING, ENVIRONMENTAL STUDY WAS FINALIZED OR IN THE FINALIZATION PHASE, BUT NO ENVIRONMENTAL LICENSE WAS REQUESTED"},{"key": "4", "value":"PROJECT HAS ENVIRONMENTAL ASSESSMENT BY THE ENVIRONMENT AREA, REQUIRES LICENSING, ENVIRONMENTAL STUDY WAS FINALIZED AND WAS REQUESTED THE ENVIRONMENTAL LICENSE"},{"key":"5","value":"PROJECT HAS ENVIRONMENTAL ASSESSMENT BY THE ENVIRONMENT AREA AND DOES NOT REQUIRE LICENSING OR HAS ENVIRONMENTAL LICENSE FOR EXECUTION AND/ OR OPERATION ISSUED AND VALID"}]'),
                                                    ("THE PROJECT HAS OTHER GAINS IN HEALTH, SAFETY, RISK AND EMERGENCY","has_other_gains_in_hsor", '[{"key": "1", "value": "NO"},{"key": "2", "value":"YES"}]'),
                                                    ("SOCIAL ASPECT & HUMAN RIGHTS IMPACT WITHOUT PROJECT EXECUTION","social_aspect_human_rights", '[{"key": "1", "value": "NO IMPACT"},{"key": "2", "value":"Impact up to 20 people without affecting physical integrity"},{"key": "3", "value":"IMPACT ON UP TO 50 PEOPLE WITHOUT AFFECTING PHYSICAL INTEGRITY. DAMAGE TO GOODS OF STATE CULTURAL RELEVANCE (OR EQUIVALENT) OR REVERSIBLE TO INFRASTRUCTURE OR PRODUCTIVE ACTIVITIES OF THE COMMUNITY WITH SOLUTIONS EXECUTED IN UP TO 1 YEAR"},{"key": "4", "value":"IMPACT ON UP TO 100 PEOPLE, OR AFFECTING THE PHYSICAL INTEGRITY OF UP TO 20 PEOPLE. DAMAGE TO GOODS OF STATE CULTURAL RELEVANCE (OR EQUIVALENT) OR REVERSIBLE TO INFRASTRUCTURE OR PRODUCTIVE ACTIVITIES OF THE COMMUNITY WITH REMEDY SOLUTIONS EXECUTED IN UP TO 1 YEAR"},{"key": "5", "value":"IMPACT OVER 100 PEOPLE, OR AFFECTING THE PHYSICAL INTEGRITY OF MORE THAN 20 PEOPLE. DAMAGE TO GOODS OF STATE CULTURAL RELEVANCE (OR EQUIVALENT) OR REVERSIBLE TO INFRASTRUCTURE OR PRODUCTIVE ACTIVITIES OF THE COMMUNITY WITH REMEDY SOLUTIONS PERFORMED BETWEEN 3 AND 5 YEARS"},{"key":"6","value":"IMPACT OVER 500 PEOPLE, EITHER AFFECTING THE PHYSICAL INTEGRITY OF MORE THAN 50 PEOPLE OR RESULTING IN 1 FATALITY. DAMAGE TO GOODS OF STATE CULTURAL RELEVANCE (OR EQUIVALENT) OR REVERSIBLE TO INFRASTRUCTURE OR PRODUCTIVE ACTIVITIES OF THE COMMUNITY WITH REMEDY SOLUTIONS EXECUTED IN MORE THAN 5 YEARS"},{"key":"7","value":"IMPACT OVER 1000 PEOPLE, OR AFFECTING THE PHYSICAL INTEGRITY OF MORE THAN 100 PEOPLE OR RESULTING IN MORE THAN 1 FATALITY. DAMAGE TO GOODS OF STATE CULTURAL RELEVANCE (OR EQUIVALENT) OR IRREVERSIBLE TO INFRASTRUCTURE OR PRODUCTIVE ACTIVITIES OF THE COMMUNITY WITH REMEDY SOLUTIONS EXECUTED IN MORE THAN 5 YEARS"}]'),
                                                    ("RESIDUAL RISK (Risk measure mitigated by the existing control environment in the Vale System)","residual_risk", '[{"key": "1", "value": "NO RISK"},{"key": "2", "value":"LOW RESIDUAL RISK"},{"key": "3", "value":"MODERATE RESIDUAL RISK"},{"key": "4", "value":"HIGH RESIDUAL RISK"},{"key": "5", "value":"VERY HIGH RESIDUAL RISK"}]'),
                                                    ("PROJECTED RESIDUAL RISK (It is the projection of the measure of risk considering the efficient controls - investments/projects)","projected_residual_risk", '[{"key": "1", "value": "VERY HIGH PROJECTED RESIDUAL RISK"},{"key": "2", "value":"HIGH PROJECTED RESIDUAL RISK"},{"key": "3", "value":"MODERATE PROJECTED RESIDUAL RISK"},{"key": "4", "value":"LOW PROJECTED RESIDUAL RISK"},{"key": "5", "value":"NO RISK"}]'),
                                                    ("RACs ATTENDANCE WITH PROJECT EXECUTION","rac_attendance_with_project", '[{"key": "1", "value": "NOT APPLICABLE"},{"key": "2", "value":"RAC 6"},{"key": "3", "value":"RAC 7"},{"key": "4", "value":"RAC 8"},{"key": "5", "value":"RAC 9"},{"key": "6", "value":"RAC 10"},{"key": "7", "value":"RAC 11"},{"key": "8", "value":"RAC 1"},{"key": "9", "value":"RAC 2"},{"key": "10", "value":"RAC 3"},{"key": "11", "value":"RAC 4"},{"key": "12", "value":"RAC 5"}]'),
                                                    ("NUMBER OF PEOPLE EXPOSED / AFFECTED TO RISK IN A POSSIBLE EVENT","number_of_people_exposed", '[{"key": "1", "value": "NO ONE"},{"key": "2", "value":"UP TO 20 PEOPLE"},{"key": "3", "value":"FROM 21 TO 100 PEOPLE"},{"key": "4", "value":"FROM 101 TO 500 PEOPLE 500 PEOPLE"},{"key": "5", "value":"OVER 500 PEOPLE"}]'),
                                                    ("FATALITY PREVENTION","fatality_prevention", '[{"key": "1", "value": "NO RECORD"},{"key": "2", "value":"RECORD OF N3/P3 IN THE COMPANY"},{"key": "3", "value":"RECORD OF N2/P2 IN THE COMPANY"},{"key": "4", "value":"RECORD OF N1/P1 IN THE COMPANY"}]'),
                                                    ("EXTRAMURAL IMPACT (IMPACT ON PEOPLE IN THE COMMUNITY) ON A POSSIBLE EVENT","extramural_impact", '[{"key": "1", "value": "NO"},{"key": "2", "value":"YES"}]'),
                                                    ("ENVIRONMENTAL IMPACT IN A POSSIBLE EVENT","enviromental_impact_in_possible_event", '[{"key": "1", "value": "NO SIGNIFICANT ENVIRONMENTAL IMPACT (LOW OR MODERATE MAGNITUDE)"},{"key": "2", "value":"HIGH-MAGNITUDE IMPACT WITH LOCAL/ADJACENT REACH. REVERSIBLE IN UP TO ONE YEAR."},{"key": "3", "value":"HIGH-MAGNITUDE IMPACT WITH CITY/COUNTY REACH. REVERSIBLE WITHIN THREE YEARS."},{"key": "4", "value":"HIGH-MAGNITUDE IMPACT WITH CITY/COUNTY OR REGIONAL REACH. IRREVERSIBLE."}]'),
                                                    ("IMPACT ON THE NUMBER OF EXPOSURES ABOVE THE Threshold Limit Value  (E.g: noise, silica, vibration etc.) - PRO-27961","impact_number_exposure", '[{"key": "1", "value": "INCREASES THE NUMBER OF EXPOSURES ABOVE Threshold Limit Value"},{"key": "2", "value":"DOES NOT IMPACT"},{"key": "3", "value":"REDUCES THE NUMBER OF EXPOSURES ABOVE Threshold Limit Value"}]'),
                                                    ("IMPACT ON NUMBER OF EXPOSURES TO HIGH AND VERY HIGH ERGONOMIC RISKS","impact_number_high_ergonomic_risk", '[{"key": "1", "value": "INCREASES THE NUMBER OF EXPOSURES TO ERGONOMIC RISK (HIGH AND VERY HIGH)"},{"key": "2", "value":"DOES NOT IMPACT"},{"key": "3", "value":"REDUCES THE NUMBER OF EXPOSURES TO ERGONOMIC RISK (HIGH AND VERY HIGH)"}]'),
